    @Override
    public CableBusRenderState getRenderState() {
        final CablePart cable = (CablePart) this.storage.getCenter();

        final CableBusRenderState renderState = new CableBusRenderState();

        if (cable != null) {
            renderState.setCableColor(cable.getCableColor());
            renderState.setCableType(cable.getCableConnectionType());
            renderState.setCoreType(CableCoreType.fromCableType(cable.getCableConnectionType()));

            // Check each outgoing connection for the desired characteristics
            for (var side : Direction.values()) {
                // Is there a connection?
                if (!cable.isConnected(side)) {
                    continue;
                }

                // If there is one, check out which type it has, but default to this cable's
                // type
                AECableType connectionType = cable.getCableConnectionType();

                // Only use the incoming cable-type of the adjacent block, if it's not a cable bus itself
                // Dense cables however also respect the adjacent cable-type since their outgoing connection
                // point would look too big for other cable types
                final BlockPos adjacentPos = this.getBlockEntity().getBlockPos().relative(side);
                var adjacentHost = GridHelper.getNodeHost(getBlockEntity().getLevel(), adjacentPos);

                if (adjacentHost != null) {
                    var adjacentType = adjacentHost.getCableConnectionType(side.getOpposite());
                    connectionType = AECableType.min(connectionType, adjacentType);
                }

                // Check if the adjacent TE is a cable bus or not
                if (adjacentHost instanceof CableBusContainer) {
                    renderState.getCableBusAdjacent().add(side);
                }

                renderState.getConnectionTypes().put(side, connectionType);
            }

            // Collect the number of channels used per side
            // We have to do this even for non-smart cables since a glass cable can display
            // a connection as smart if the
            // adjacent block entity requires it
            for (var side : Direction.values()) {
                int channels = cable.getCableConnectionType().isSmart() ? cable.getChannelsOnSide(side) : 0;
                renderState.getChannelsOnSide().put(side, channels);
            }
        }

        // Determine attachments and facades
        for (var side : IPart.ATTACHMENT_POINTS) {
            renderState.setFacade(side, getFacadeRenderState(side));

            var part = this.getPart(side);

            if (part == null) {
                continue;
            }

            var builder = ModelData.builder();
            part.collectModelData(builder);
            var partModelData = builder.build();

            renderState.getAttachments().put(side, new PartRenderState(part.getPartItem(), partModelData));

            // This will add the part's bounding boxes to the render state, which is
            // required for facades
            final IPartCollisionHelper bch = new BusCollisionHelper(renderState.getBoundingBoxes(), side, true);
            part.getBoxes(bch);

            // Some attachments want a thicker cable than glass, account for that
            var desiredType = part.getDesiredConnectionType();
            if (renderState.getCoreType() == CableCoreType.GLASS
                    && (desiredType == AECableType.SMART || desiredType == AECableType.COVERED)) {
                renderState.setCoreType(CableCoreType.COVERED);
            }

            int length = (int) part.getCableConnectionLength(null);
            if (length > 0 && length <= 8) {
                renderState.getAttachmentConnections().put(side, length);
            }
        }

        return renderState;
    }

    @Nullable
    private BlockState getFacadeRenderState(Direction side) {
        // Store the "masqueraded" itemstack for the given side, if there is a facade
        var facade = this.storage.getFacade(side);

        if (facade != null) {
            return facade.getBlockState();
        }

        return null;
    }

    /**
     * See {@link BlockState#getShape}
     */
    public VoxelShape getShape() {
        var currentRenderMode = PartHelper.getCableRenderMode();
        if (cachedShape == null || currentRenderMode != cachedShapeCableRenderMode) {
            cachedShape = createShape(false, false);
            cachedShapeCableRenderMode = currentRenderMode;
        }

        return cachedShape;
    }

    /**
     * See {@link BlockState#getCollisionShape}
     */
    public VoxelShape getCollisionShape(CollisionContext context) {
        // This is a hack for annihilation planes
        var itemEntity = context instanceof EntityCollisionContext entityContext
                && entityContext.getEntity() instanceof ItemEntity;

        if (itemEntity) {
            if (cachedCollisionShapeLiving == null) {
                cachedCollisionShapeLiving = createShape(true, true);
            }
            return cachedCollisionShapeLiving;
        } else {
            if (cachedCollisionShape == null) {
                cachedCollisionShape = createShape(true, false);
            }
            return cachedCollisionShape;
        }
    }

    private VoxelShape createShape(boolean forCollision, boolean forItemEntity) {
        final List<AABB> boxes = new ArrayList<>();

        var fc = this.getFacadeContainer();
        for (Direction s : Platform.DIRECTIONS_WITH_NULL) {
            final IPartCollisionHelper bch = new BusCollisionHelper(boxes, s, !forCollision);

            final IPart part = this.getPart(s);
            if (part != null) {
                part.getBoxes(bch);
            }

            if ((PartHelper.getCableRenderMode().opaqueFacades || forCollision)
                    && s != null) {
                var fp = fc.getFacade(s);
                if (fp != null) {
                    fp.getBoxes(bch, forItemEntity);
                }
            }
        }

        return VoxelShapeCache.get(boxes);
    }

    private void invalidateShapes() {
        cachedShape = null;
        cachedCollisionShape = null;
        cachedCollisionShapeLiving = null;
    }

    private void updateNeighborShapeOnSide(Direction side) {
        if (side == null) {
            return; // side can be null for cable
        }
        // Update the shape of the neighbor asynchronously (i.e. for walls)
        var be = getBlockEntity();
        if (be != null && be.getLevel() != null && !be.getLevel().isClientSide()) {
            TickHandler.instance().addCallable(be.getLevel(), level -> {
                if (!be.isRemoved()) {
                    var ourPos = be.getBlockPos();
                    var neighborPos = ourPos.relative(side);
                    var neighborState = level.getBlockState(neighborPos);
                    var ourState = be.getBlockState();
                    BlockState newNeighborState = neighborState.updateShape(level, level, neighborPos,
                            side.getOpposite(), ourPos, ourState, level.getRandom());
                    Block.updateOrDestroy(neighborState, newNeighborState, level, neighborPos, Block.UPDATE_ALL,
                            Block.UPDATE_LIMIT);
                }
            });
        }
    }

    @Nullable
    public <T> T getPartRendererCache(Class<T> cacheClass) {
        try {
            return cacheClass.cast(partRendererCache);
        } catch (ClassCastException ignored) {
            return null;
        }
    }

    public void setPartRendererCache(Object partRendererCache) {
        this.partRendererCache = partRendererCache;
    }
}

package appeng.recipes.game;

import java.util.List;

import com.mojang.serialization.MapCodec;
import com.mojang.serialization.codecs.RecordCodecBuilder;

import net.minecraft.core.NonNullList;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.core.registries.Registries;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.crafting.CraftingInput;
import net.minecraft.world.item.crafting.CustomRecipe;
import net.minecraft.world.item.crafting.RecipeSerializer;
import net.minecraft.world.item.crafting.display.RecipeDisplay;
import net.minecraft.world.item.crafting.display.SlotDisplay;
import net.minecraft.world.level.Level;

/**
 * Allows swapping out the storage component of a cell without having to empty it first.
 */
public class StorageCellUpgradeRecipe extends CustomRecipe {
    private final Item inputCell;
    private final Item inputComponent;
    private final Item resultCell;
    private final Item resultComponent;

    public StorageCellUpgradeRecipe(Item inputCell, Item inputComponent, Item resultCell, Item resultComponent) {
        this.inputCell = inputCell;
        this.inputComponent = inputComponent;
        this.resultCell = resultCell;
        this.resultComponent = resultComponent;
    }

    public static final MapCodec<StorageCellUpgradeRecipe> CODEC = RecordCodecBuilder.mapCodec(builder -> builder.group(
            BuiltInRegistries.ITEM.byNameCodec().fieldOf("input_cell")
                    .forGetter(StorageCellUpgradeRecipe::getInputCell),
            BuiltInRegistries.ITEM.byNameCodec().fieldOf("input_component")
                    .forGetter(StorageCellUpgradeRecipe::getInputComponent),
            BuiltInRegistries.ITEM.byNameCodec().fieldOf("result_cell")
                    .forGetter(StorageCellUpgradeRecipe::getResultCell),
            BuiltInRegistries.ITEM.byNameCodec().fieldOf("result_component")
                    .forGetter(StorageCellUpgradeRecipe::getResultComponent))
            .apply(builder, StorageCellUpgradeRecipe::new));

    public static final StreamCodec<RegistryFriendlyByteBuf, StorageCellUpgradeRecipe> STREAM_CODEC = StreamCodec
            .composite(
                    ByteBufCodecs.registry(Registries.ITEM), StorageCellUpgradeRecipe::getInputCell,
                    ByteBufCodecs.registry(Registries.ITEM), StorageCellUpgradeRecipe::getInputComponent,
                    ByteBufCodecs.registry(Registries.ITEM), StorageCellUpgradeRecipe::getResultCell,
                    ByteBufCodecs.registry(Registries.ITEM), StorageCellUpgradeRecipe::getResultComponent,
                    StorageCellUpgradeRecipe::new);

    public static final RecipeSerializer<StorageCellUpgradeRecipe> SERIALIZER = new RecipeSerializer<>(CODEC,
            STREAM_CODEC);

    public Item getInputCell() {
        return inputCell;
    }

    public Item getInputComponent() {
        return inputComponent;
    }

    public Item getResultCell() {
        return resultCell;
    }

    public Item getResultComponent() {
        return resultComponent;
    }

    @Override
    public boolean matches(CraftingInput container, Level level) {
        var cellsFound = 0;
        var componentsFound = 0;

        for (int i = 0; i < container.size(); i++) {
            var stack = container.getItem(i);
            if (!stack.isEmpty()) {
                if (stack.is(inputCell)) {
                    // Also bail out if somehow someone managed to stack cells (since we replace it with a component)
                    cellsFound += stack.getCount();
                } else if (stack.is(inputComponent)) {
                    componentsFound++;
                } else {
                    return false;
                }

                if (cellsFound > 1 || componentsFound > 1) {
                    return false;
                }
            }
        }

        return cellsFound == 1 && componentsFound == 1;
    }

    @Override
    public ItemStack assemble(CraftingInput container) {
        ItemStack foundCell = ItemStack.EMPTY;
        var componentsFound = 0;

        for (int i = 0; i < container.size(); i++) {
            var stack = container.getItem(i);
            if (!stack.isEmpty()) {
                if (stack.is(inputCell)) {
                    if (stack.getCount() > 1 || !foundCell.isEmpty()) {
                        return ItemStack.EMPTY; // More than one cell found
                    }
                    foundCell = stack;
                } else if (stack.is(inputComponent)) {
                    if (++componentsFound > 1) {
                        return ItemStack.EMPTY; // More than one component found
                    }
                } else {
                    return ItemStack.EMPTY; // Other item found
                }
            }
        }

        if (foundCell.isEmpty() || componentsFound == 0) {
            return ItemStack.EMPTY;
        } else {
            return foundCell.transmuteCopy(resultCell, 1);
        }
    }

    @Override
    public NonNullList<ItemStack> getRemainingItems(CraftingInput input) {
        var remainder = NonNullList.withSize(input.size(), ItemStack.EMPTY);

        for (int i = 0; i < remainder.size(); ++i) {
            var stack = input.getItem(i);
            if (stack.is(inputCell)) {
                // We replace the cell with the component since it is unstackable and forced to be in match
                remainder.set(i, new ItemStack(resultComponent));
            } else {
                var stackRemainder = stack.getCraftingRemainder();
                remainder.set(i, stackRemainder != null ? stackRemainder.create() : ItemStack.EMPTY);
            }
        }

        return remainder;
    }

    @Override
    public RecipeSerializer<StorageCellUpgradeRecipe> getSerializer() {
        return SERIALIZER;
    }

    @Override
    public List<RecipeDisplay> display() {
        return List.of(
                new StorageCellUpgradeDisplay(
                        new SlotDisplay.ItemSlotDisplay(inputCell),
                        new SlotDisplay.ItemSlotDisplay(inputComponent),
                        new SlotDisplay.ItemSlotDisplay(resultCell),
                        new SlotDisplay.ItemSlotDisplay(resultComponent)));
    }
}
